def soma_recursiva(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError("Use inteiro não negativo")
    if n == 0:
        return 0
    return n + soma_recursiva(n - 1)
assert soma_recursiva(0) == 0
assert soma_recursiva(4) == 10

for n in range(101):
    assert soma_recursiva(n)==n*(n+1)//2
for bad in (-1,2.5,True):
    try:soma_recursiva(bad)
    except ValueError:pass
    else:raise AssertionError("Entrada deveria ser rejeitada")
